import { useMemo, useState, type FormEvent, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import { ArrowRight, Bell, BookOpen, Check, CircleHelp, ClipboardList, Compass, GraduationCap, HeartHandshake, House, Leaf, LockKeyhole, LogOut, MapPin, Menu, PackageOpen, Pencil, Plus, Search, ShieldCheck, Sprout, Trash2, UserRound, Users, X, type LucideIcon } from 'lucide-react';
import {
  getGetAdminStatisticsQueryKey, getGetDashboardQueryKey, getGetImpactQueryKey, getGetListingQueryKey, getGetMeQueryKey, getHealthCheckQueryKey, getListAdminListingsQueryKey, getListAdminUsersQueryKey, getListCategoriesQueryKey, getListListingsQueryKey, getListNotificationsQueryKey, getListRequestsQueryKey, setAuthTokenGetter,
  useAcceptRequest, useCancelRequest, useCompleteRequest, useCreateListing, useCreateRequest, useDeleteListing, useDisableUser, useGetAdminStatistics, useGetDashboard, useGetImpact, useGetListing, useGetMe, useHealthCheck, useListAdminListings, useListAdminUsers, useListCategories, useListListings, useListNotifications, useListRequests, useLogin, useMarkAllNotificationsRead, useMarkNotificationRead, useRegister, useRejectRequest, useRemoveAdminListing, useUpdateListing,
  type Condition, type ItemRequest, type Listing, type ListingInput, type ListingType, type User,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import './index.css';

const queryClient = new QueryClient();
setAuthTokenGetter(() => localStorage.getItem('campusloop_token'));

const colors = ['bg-[#e7d6ae]', 'bg-[#c6d9ca]', 'bg-[#e9c8b8]', 'bg-[#c6dce1]'];
const pretty = (value?: string | null) => value ? value.replaceAll('_', ' ').toLowerCase().replace(/^\w/, (c) => c.toUpperCase()) : '—';
const initials = (name = 'CampusLoop') => name.split(' ').map((word) => word[0]).slice(0, 2).join('').toUpperCase();
const dateLabel = (value?: string) => value ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric' }).format(new Date(value)) : '';

function Logo({ dark = false }: { dark?: boolean }) {
  return <Link href="/" className={`flex items-center gap-2.5 ${dark ? 'text-[#f8f4e9]' : 'text-[#20443d]'}`} data-testid="link-logo">
    <span className={`grid size-9 place-items-center rounded-[11px] ${dark ? 'bg-[#e8d26e] text-[#20443d]' : 'bg-[#20443d] text-[#f8f4e9]'}`}><Sprout size={19} strokeWidth={2.5} /></span>
    <span className="display text-xl font-semibold tracking-[-.03em]">Campus<span className={dark ? 'text-[#e8d26e]' : 'text-[#bb801d]'}>Loop</span></span>
  </Link>;
}

function Avatar({ user, size = 'size-9' }: { user?: Pick<User, 'fullName' | 'profileImageUrl'> | null; size?: string }) {
  return user?.profileImageUrl ? <img src={user.profileImageUrl} alt={user.fullName} className={`${size} rounded-full object-cover`} data-testid="img-avatar" /> :
    <span className={`${size} grid shrink-0 place-items-center rounded-full bg-[#e7d6ae] text-xs font-bold text-[#20443d]`} data-testid="text-avatar">{initials(user?.fullName)}</span>;
}

function Button({ children, variant = 'primary', className = '', type = 'button', onClick, disabled, testId }: { children: ReactNode; variant?: 'primary' | 'outline' | 'ghost' | 'danger' | 'cream'; className?: string; type?: 'button' | 'submit'; onClick?: () => void; disabled?: boolean; testId?: string }) {
  const styles = { primary: 'bg-[#20443d] text-[#f8f4e9] hover:bg-[#2d5e54]', outline: 'border border-[#b7c5bc] bg-transparent text-[#20443d] hover:border-[#20443d] hover:bg-[#edf0e6]', ghost: 'text-[#52736b] hover:bg-[#eaf0e8]', danger: 'bg-[#f6ded7] text-[#9b392e] hover:bg-[#efc6bc]', cream: 'bg-[#e8d26e] text-[#20443d] hover:bg-[#f1df83]' };
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`} data-testid={testId}>{children}</button>;
}

function Notice({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-[#decdb0] bg-[#f7efd9] p-7 text-center" data-testid="status-empty">
    <div className="mx-auto mb-3 grid size-11 place-items-center rounded-full bg-[#e7d6ae] text-[#20443d]"><Sprout size={21} /></div>
    <h3 className="display text-xl font-semibold text-[#20443d]">{title}</h3><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-[#52736b]">{detail}</p>{action && <div className="mt-4">{action}</div>}
  </div>;
}

function LoadingState({ rows = 3 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="status-loading">{Array.from({ length: rows }).map((_, index) => <div className="skeleton h-24 rounded-2xl" key={index} />)}</div>;
}

function ErrorState({ retry }: { retry?: () => void }) {
  return <Notice title="The loop paused" detail="We couldn't reach the campus exchange right now. Try again in a moment." action={retry && <Button variant="outline" onClick={retry} testId="button-retry">Try again</Button>} />;
}

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const { data: me } = useGetMe();
  const notifications = useListNotifications({ query: { enabled: Boolean(me), queryKey: getListNotificationsQueryKey() } });
  const markRead = useMarkNotificationRead();
  const markAll = useMarkAllNotificationsRead();
  const [mobileOpen, setMobileOpen] = useState(false);
  const unread = notifications.data?.filter((item) => !item.read).length || 0;
  const nav = [
    { href: '/marketplace', label: 'Browse resources', icon: Compass },
    { href: '/dashboard', label: 'My dashboard', icon: House },
    { href: '/impact', label: 'Campus impact', icon: Leaf },
  ];
  if (me?.role === 'ADMIN') nav.push({ href: '/admin', label: 'Admin desk', icon: ShieldCheck });
  return <div className="min-h-[100dvh] bg-[#f6f3ea] text-[#20443d]">
    <aside className="fixed inset-y-0 left-0 z-40 hidden w-[250px] flex-col bg-[#20443d] px-5 py-6 lg:flex">
      <Logo dark />
      <div className="mt-12 flex flex-1 flex-col">
        <p className="mono mb-3 px-3 text-[#9db8aa]">Campus exchange</p>
        <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm ${location === href ? 'bg-[#315d54] text-[#f5db72]' : 'text-[#c5d2c8] hover:bg-[#2b554d] hover:text-[#f8f4e9]'}`} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={17} />{label}</Link>)}</nav>
        <div className="mt-auto rounded-2xl bg-[#2b554d] p-4"><p className="text-xs font-semibold text-[#f5db72]">Small swaps, big difference.</p><p className="mt-2 text-xs leading-5 text-[#c5d2c8]">Every item kept in use is one less thing headed to landfill.</p><Link href="/impact" className="mt-3 inline-flex items-center gap-1 text-xs font-semibold text-[#f8f4e9]" data-testid="link-impact-card">See our numbers <ArrowRight size={13} /></Link></div>
      </div>
      {me ? <div className="mt-7 flex items-center gap-3 border-t border-[#315d54] pt-5"><Avatar user={me} size="size-8" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-[#f8f4e9]" data-testid="text-current-user">{me.fullName}</p><p className="truncate text-xs text-[#9db8aa]">{me.college}</p></div><button className="text-[#c5d2c8] hover:text-[#f5db72]" onClick={() => { localStorage.removeItem('campusloop_token'); setLocation('/'); }} data-testid="button-logout" aria-label="Sign out"><LogOut size={16} /></button></div> : <Link href="/login" className="mt-7 flex items-center justify-between rounded-xl bg-[#e8d26e] px-3 py-3 text-sm font-bold text-[#20443d]" data-testid="link-sidebar-login">Sign in <ArrowRight size={16} /></Link>}
    </aside>
    <header className="sticky top-0 z-30 flex h-[70px] items-center justify-between border-b border-[#e1ded3] bg-[#f6f3ea]/95 px-5 backdrop-blur lg:ml-[250px] lg:px-10">
      <div className="lg:hidden"><Logo /></div>
      <div className="hidden items-center gap-2 text-sm text-[#52736b] lg:flex"><span className="size-2 rounded-full bg-[#79a875]" /> Connected to your campus</div>
      <div className="ml-auto flex items-center gap-2">
        <div className="relative"><button className="grid size-10 place-items-center rounded-xl text-[#52736b] hover:bg-[#e9eee6]" onClick={() => markAll.mutate(undefined, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) })} data-testid="button-notifications" aria-label="Notifications"><Bell size={19} />{unread > 0 && <span className="absolute right-1 top-1 size-2 rounded-full bg-[#d36e52]" />}</button>{unread > 0 && <div className="absolute right-0 top-12 hidden w-72 rounded-2xl border border-[#ddd8c9] bg-[#fbfaf5] p-3 shadow-xl group-focus-within:block">{notifications.data?.filter((item) => !item.read).slice(0, 3).map((item) => <button key={item.id} className="block w-full rounded-xl p-2 text-left hover:bg-[#f0eee5]" onClick={() => markRead.mutate({ id: item.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) })} data-testid={`button-notification-${item.id}`}><p className="text-xs font-bold">{item.title}</p><p className="mt-1 text-xs text-[#52736b]">{item.message}</p></button>)}</div>}</div>
        <Link href="/profile" className="grid size-10 place-items-center rounded-xl text-[#52736b] hover:bg-[#e9eee6] lg:hidden" data-testid="link-mobile-profile"><UserRound size={18} /></Link>
        <button className="grid size-10 place-items-center rounded-xl text-[#52736b] hover:bg-[#e9eee6] lg:hidden" onClick={() => setMobileOpen(!mobileOpen)} data-testid="button-mobile-menu"><Menu size={19} /></button>
      </div>
      {mobileOpen && <div className="absolute left-0 right-0 top-[70px] border-b border-[#dedbd0] bg-[#f6f3ea] p-4 lg:hidden">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileOpen(false)} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold hover:bg-[#e9eee6]" data-testid={`link-mobile-${label}`}><Icon size={17} />{label}</Link>)}</div>}
    </header>
    <main className="lg:ml-[250px]">{children}</main>
  </div>;
}

function Page({ eyebrow, title, detail, children, action }: { eyebrow?: string; title: string; detail?: string; children: ReactNode; action?: ReactNode }) {
  return <div className="mx-auto max-w-[1260px] px-5 py-9 sm:px-8 lg:px-12 lg:py-12"><div className="mb-9 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div>{eyebrow && <p className="mono mb-3 text-[#ae7620]">{eyebrow}</p>}<h1 className="display max-w-3xl text-4xl font-semibold leading-[1.05] tracking-[-.035em] text-[#20443d] sm:text-5xl" data-testid="text-page-title">{title}</h1>{detail && <p className="mt-3 max-w-2xl text-[15px] leading-7 text-[#52736b]">{detail}</p>}</div>{action}</div>{children}</div>;
}

function Landing() {
  const { data: health } = useHealthCheck({ query: { staleTime: 60_000, queryKey: getHealthCheckQueryKey() } });
  const impact = useGetImpact();
  const recent = useListListings({ page: 0, size: 1, sort: 'newest' });
  const categories = useListCategories();
  const featured = recent.data?.content[0];
  const reused = impact.data?.itemsReused;
  return <div className="min-h-[100dvh] overflow-hidden bg-[#f6f3ea] text-[#20443d]">
    <header className="mx-auto flex max-w-[1280px] items-center justify-between px-5 py-6 sm:px-8"><Logo /><div className="flex items-center gap-2"><Link href="/login" className="hidden px-4 py-2 text-sm font-semibold text-[#52736b] sm:block" data-testid="link-landing-login">Sign in</Link><Link href="/register" className="rounded-xl bg-[#20443d] px-4 py-2.5 text-sm font-semibold text-[#f8f4e9] hover:bg-[#2d5e54]" data-testid="link-landing-register">Join the loop <ArrowRight className="ml-1 inline" size={15} /></Link></div></header>
    <section className="relative mx-auto grid max-w-[1280px] gap-14 px-5 pb-20 pt-14 sm:px-8 lg:grid-cols-[1.05fr_.95fr] lg:items-center lg:pb-32 lg:pt-24"><div className="relative z-10 rise"><p className="mono mb-6 flex items-center gap-2 text-[#ae7620]"><span className="size-2 rounded-full bg-[#ae7620]" /> Made for campus, by campus</p><h1 className="display max-w-3xl text-[clamp(3.6rem,8vw,7.3rem)] font-semibold leading-[.88] tracking-[-.06em] text-[#20443d]">Good things<br /><span className="text-[#ae7620]">keep going.</span></h1><p className="mt-8 max-w-lg text-lg leading-8 text-[#52736b]">CampusLoop is the resource exchange for the things sitting unused in your lab, lounge, or locker — waiting for the right student.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/marketplace" className="inline-flex items-center gap-2 rounded-xl bg-[#20443d] px-5 py-3.5 text-sm font-bold text-[#f8f4e9]" data-testid="link-hero-browse">Explore the marketplace <ArrowRight size={17} /></Link><Link href="/register" className="inline-flex items-center gap-2 rounded-xl border border-[#b7c5bc] px-5 py-3.5 text-sm font-bold text-[#20443d] hover:bg-[#e9eee6]" data-testid="link-hero-register">Share something useful</Link></div><div className="mt-12 flex items-center gap-4 text-sm text-[#52736b]"><div className="flex -space-x-2"><span className="grid size-8 place-items-center rounded-full border-2 border-[#f6f3ea] bg-[#c6d9ca] text-xs font-bold">AM</span><span className="grid size-8 place-items-center rounded-full border-2 border-[#f6f3ea] bg-[#e9c8b8] text-xs font-bold">JR</span><span className="grid size-8 place-items-center rounded-full border-2 border-[#f6f3ea] bg-[#c6dce1] text-xs font-bold">TK</span></div><span><strong className="text-[#20443d]">Students are already swapping</strong><br />notes, gear, and good ideas.</span></div></div><div className="relative min-h-[390px] rise [animation-delay:.12s]"><div className="absolute right-0 top-3 h-[360px] w-[88%] rounded-[42%_58%_52%_48%/43%_40%_60%_57%] bg-[#d7e4cf]" /><div className="absolute bottom-5 left-3 h-[290px] w-[84%] rounded-[54%_46%_35%_65%/63%_51%_49%_37%] bg-[#e8d26e]" /><div className="absolute left-[19%] top-[13%] w-[60%] rotate-[-7deg] rounded-3xl border border-[#20443d]/10 bg-[#fbfaf5] p-4 shadow-2xl shadow-[#20443d]/10"><div className="flex items-center justify-between border-b border-[#e7e2d6] pb-3"><span className="mono text-[#ae7620]">recently shared</span><Sprout className="text-[#789c78]" size={18} /></div><div className="mt-5 flex gap-3"><div className="grid size-14 place-items-center rounded-2xl bg-[#c6dce1] text-[#20443d]"><BookOpen size={25} /></div><div className="min-w-0"><p className="display truncate text-lg font-semibold">{featured?.title ?? 'A useful thing, waiting'}</p><p className="mt-1 truncate text-xs text-[#52736b]">{featured ? `${featured.category.name} · ${pretty(featured.condition)}` : 'Shared by your campus'}</p></div></div><div className="mt-6 flex items-center justify-between border-t border-[#e7e2d6] pt-3 text-xs text-[#52736b]"><span>{featured ? `Shared by ${featured.owner.fullName}` : 'New resources appear here'}</span>{featured ? <Link href={`/marketplace/${featured.id}`} className="font-bold text-[#20443d]">Request it <ArrowRight className="inline" size={12} /></Link> : <span className="font-bold text-[#20443d]">Browse the loop <ArrowRight className="inline" size={12} /></span>}</div></div><div className="absolute bottom-8 right-0 rotate-[8deg] rounded-2xl bg-[#20443d] px-5 py-4 text-[#f8f4e9] shadow-xl"><p className="mono text-[#e8d26e]">recorded reuse</p><p className="display mt-1 text-3xl">{reused?.toLocaleString() ?? '—'}</p><p className="text-xs text-[#c5d2c8]">items found new homes</p></div></div></section>
    <section className="bg-[#20443d] px-5 py-20 text-[#f8f4e9] sm:px-8"><div className="mx-auto max-w-[1180px]"><p className="mono text-[#e8d26e]">The campus rhythm</p><div className="mt-8 grid gap-10 md:grid-cols-3"><div><p className="display text-3xl leading-tight">Someone has what you need.</p><p className="mt-4 text-sm leading-6 text-[#c5d2c8]">A poster printer. A spare lab coat. The exact textbook for week 7.</p></div><div><p className="display text-3xl leading-tight">You have what they need.</p><p className="mt-4 text-sm leading-6 text-[#c5d2c8]">List what is gathering dust and put it back in rotation.</p></div><div><p className="display text-3xl leading-tight">The loop gets stronger.</p><p className="mt-4 text-sm leading-6 text-[#c5d2c8]">Every completed exchange keeps value on campus and out of the waste stream.</p></div></div></div></section>
    <section className="mx-auto grid max-w-[1180px] gap-8 px-5 py-20 sm:px-8 md:grid-cols-[.9fr_1.1fr] md:items-center"><div><p className="mono text-[#ae7620]">How it works</p><h2 className="display mt-4 text-4xl font-semibold leading-tight tracking-tight">A simple handoff,<br />made visible.</h2><p className="mt-5 max-w-md leading-7 text-[#52736b]">CampusLoop turns a quiet corner of campus into a living catalog. Find the item, send a thoughtful note, agree on a handoff, and mark the exchange complete.</p></div><div className="space-y-3">{[['01', 'Find it', 'Search resources shared by students and campus organizations.'], ['02', 'Request it', 'Tell the owner what you need it for and when you can collect it.'], ['03', 'Pass it on', 'Complete the exchange and keep the good stuff moving.']].map(([number, title, copy]) => <div key={number} className="flex gap-5 rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5"><span className="mono pt-1 text-[#ae7620]">{number}</span><div><h3 className="font-bold">{title}</h3><p className="mt-1 text-sm leading-6 text-[#52736b]">{copy}</p></div></div>)}</div></section>
    <section className="border-t border-[#dedbd0] px-5 py-16 sm:px-8"><div className="mx-auto max-w-[1180px]"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mono text-[#ae7620]">Browse by need</p><h2 className="display mt-3 text-3xl font-semibold">What is moving around campus?</h2></div><Link href="/marketplace" className="text-sm font-bold text-[#52736b]">See every resource <ArrowRight className="ml-1 inline" size={14} /></Link></div><div className="mt-6 flex flex-wrap gap-2">{categories.data?.slice(0, 8).map((category) => <Link key={category.id} href={`/marketplace?category=${category.slug}`} className="rounded-full border border-[#c8d2c6] bg-[#fbfaf5] px-4 py-2 text-sm font-semibold hover:border-[#20443d]" data-testid={`link-category-${category.slug}`}>{category.name}</Link>)}</div></div></section>
    <footer className="border-t border-[#dedbd0] px-5 py-8 sm:px-8"><div className="mx-auto flex max-w-[1180px] flex-col justify-between gap-3 text-xs text-[#52736b] sm:flex-row"><span>CampusLoop · Built for the shared campus.</span><span>{health?.status === 'ok' ? 'Systems ready' : 'A resource exchange for your campus'}</span></div></footer>
  </div>;
}

function ListingCard({ item, index = 0 }: { item: Listing; index?: number }) {
  return <Link href={`/marketplace/${item.id}`} className="group lift overflow-hidden rounded-2xl border border-[#dedbd0] bg-[#fbfaf5]" data-testid={`card-listing-${item.id}`}><div className={`relative flex h-44 items-end justify-between overflow-hidden ${colors[index % colors.length]} p-4`}><div className="absolute -right-5 -top-10 size-36 rounded-full border-[22px] border-[#20443d]/[.08]" /><span className="mono relative rounded-full bg-[#fbfaf5]/80 px-2.5 py-1 text-[#20443d]">{pretty(item.listingType)}</span><span className="relative grid size-12 place-items-center rounded-2xl bg-[#fbfaf5]/70 text-[#20443d]"><PackageOpen size={24} /></span></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="mono text-[#ae7620]">{item.category.name}</p><h3 className="mt-2 line-clamp-2 text-lg font-bold text-[#20443d]">{item.title}</h3></div><span className="shrink-0 text-xs font-semibold text-[#52736b]">{item.availableQuantity}/{item.quantity} left</span></div><p className="mt-3 line-clamp-2 text-sm leading-6 text-[#52736b]">{item.description}</p><div className="mt-5 flex items-center justify-between border-t border-[#e9e4d8] pt-4 text-xs text-[#52736b]"><span className="flex items-center gap-1"><MapPin size={13} />{item.location}</span><span className="flex items-center gap-1 font-semibold text-[#20443d]">View <ArrowRight size={13} /></span></div></div></Link>;
}

function Marketplace() {
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const [type, setType] = useState('');
  const [sort, setSort] = useState<'newest' | 'oldest' | 'updated'>('newest');
  const params = useMemo(() => ({ search: search || undefined, category: category || undefined, listingType: (type || undefined) as ListingType | undefined, available: true, page: 0, size: 24, sort }), [search, category, type, sort]);
  const listings = useListListings(params);
  const categories = useListCategories();
  const content = listings.data?.content || [];
  return <Shell><Page eyebrow="The marketplace" title="Useful things, already on campus." detail="Browse resources shared by students, labs, and organizations. Search by what you need, then make a clear request." action={<Link href="/dashboard" className="inline-flex items-center gap-2 rounded-xl bg-[#e8d26e] px-4 py-2.5 text-sm font-bold text-[#20443d]" data-testid="link-marketplace-share"><Plus size={16} /> Share an item</Link>}><div className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-3 sm:p-4"><div className="flex flex-col gap-3 lg:flex-row"><label className="relative flex-1"><Search className="absolute left-4 top-3.5 text-[#78958b]" size={18} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search textbooks, gear, supplies..." className="h-11 w-full rounded-xl border border-[#dedbd0] bg-[#f6f3ea] pl-11 pr-4 text-sm outline-none focus:border-[#20443d]" data-testid="input-marketplace-search" /></label><select value={category} onChange={(event) => setCategory(event.target.value)} className="h-11 rounded-xl border border-[#dedbd0] bg-[#f6f3ea] px-3 text-sm outline-none" data-testid="select-marketplace-category"><option value="">All categories</option>{categories.data?.map((item) => <option key={item.id} value={item.slug}>{item.name}</option>)}</select><select value={type} onChange={(event) => setType(event.target.value)} className="h-11 rounded-xl border border-[#dedbd0] bg-[#f6f3ea] px-3 text-sm outline-none" data-testid="select-marketplace-type"><option value="">Everything</option><option value="DONATE">Donations</option><option value="EXCHANGE">Exchanges</option></select><select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} className="h-11 rounded-xl border border-[#dedbd0] bg-[#f6f3ea] px-3 text-sm outline-none" data-testid="select-marketplace-sort"><option value="newest">Newest first</option><option value="updated">Recently updated</option><option value="oldest">Oldest first</option></select></div></div><div className="mt-7 flex items-center justify-between"><p className="text-sm text-[#52736b]" data-testid="text-listing-count"><strong className="text-[#20443d]">{listings.data?.totalElements ?? '—'}</strong> resources in the loop</p><span className="mono text-[#78958b]">live campus catalog</span></div>{listings.isLoading ? <div className="mt-5 grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><LoadingState rows={6} /></div> : listings.isError ? <div className="mt-5"><ErrorState retry={() => listings.refetch()} /></div> : content.length === 0 ? <div className="mt-5"><Notice title="Nothing here yet" detail="Try a wider search, or be the first person to share something useful with campus." action={<Link href="/dashboard" className="inline-flex rounded-xl bg-[#20443d] px-4 py-2.5 text-sm font-semibold text-[#f8f4e9]" data-testid="link-empty-create">Share a resource</Link>} /></div> : <div className="mt-5 grid gap-5 sm:grid-cols-2 xl:grid-cols-3">{content.map((item, index) => <ListingCard key={item.id} item={item} index={index} />)}</div>}</Page></Shell>;
}

function ListingDetail() {
  const params = useParams<{ id: string }>();
  const id = Number(params.id);
  const listing = useGetListing(id);
  const createRequest = useCreateRequest();
  const [message, setMessage] = useState('');
  const [requested, setRequested] = useState(false);
  if (listing.isLoading) return <Shell><Page title="Loading resource" detail="Pulling the details from campus..."><LoadingState rows={2} /></Page></Shell>;
  if (listing.isError || !listing.data) return <Shell><Page title="Resource not found"><ErrorState /></Page></Shell>;
  const item = listing.data;
  const submit = (event: FormEvent) => { event.preventDefault(); createRequest.mutate({ data: { listingId: id, message } }, { onSuccess: () => { setRequested(true); setMessage(''); queryClient.invalidateQueries({ queryKey: getListRequestsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetListingQueryKey(id) }); } }); };
  return <Shell><div className="mx-auto max-w-[1100px] px-5 py-8 sm:px-8 lg:px-12"><Link href="/marketplace" className="mb-8 inline-flex items-center gap-2 text-sm font-semibold text-[#52736b]" data-testid="link-back-marketplace">← Back to marketplace</Link><div className="grid gap-8 lg:grid-cols-[1.05fr_.95fr]"><div className={`relative flex min-h-[360px] items-end overflow-hidden rounded-[28px] ${colors[id % colors.length]} p-7`}><div className="absolute right-10 top-8 size-56 rounded-full border-[36px] border-[#20443d]/[.08]" /><div className="absolute bottom-10 left-10 size-32 rounded-full border-[20px] border-[#fbfaf5]/50" /><div className="relative flex w-full items-end justify-between"><div><span className="mono rounded-full bg-[#fbfaf5]/75 px-3 py-1.5">{pretty(item.listingType)}</span><p className="display mt-5 max-w-lg text-4xl font-semibold leading-tight text-[#20443d]">{item.title}</p></div><PackageOpen className="text-[#20443d]/60" size={70} strokeWidth={1} /></div></div><div><p className="mono text-[#ae7620]">{item.category.name} · {pretty(item.condition)}</p><h1 className="display mt-3 text-4xl font-semibold leading-tight tracking-tight text-[#20443d]" data-testid="text-listing-title">{item.title}</h1><p className="mt-5 leading-7 text-[#52736b]" data-testid="text-listing-description">{item.description}</p><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl bg-[#edf0e6] p-4"><p className="mono text-[#78958b]">Available</p><p className="mt-2 text-2xl font-bold">{item.availableQuantity} <span className="text-sm font-normal text-[#52736b]">of {item.quantity}</span></p></div><div className="rounded-xl bg-[#edf0e6] p-4"><p className="mono text-[#78958b]">Pickup</p><p className="mt-2 truncate text-sm font-bold">{item.location}</p></div></div><div className="mt-6 flex items-center gap-3 border-y border-[#dedbd0] py-4"><Avatar user={{ fullName: item.owner.fullName, profileImageUrl: null }} /><div><p className="text-sm font-bold">{item.owner.fullName}</p><p className="text-xs text-[#52736b]">{item.owner.department} · shared {dateLabel(item.createdAt)}</p></div></div>{requested ? <div className="mt-6 rounded-2xl border border-[#b8d2ba] bg-[#e7f1e5] p-5"><div className="flex items-center gap-2 font-bold text-[#315d38]"><Check size={18} /> Request sent</div><p className="mt-2 text-sm leading-6 text-[#52736b]">The owner has your note. You can follow its progress from your dashboard.</p><Link href="/dashboard" className="mt-3 inline-flex text-sm font-bold text-[#315d38]" data-testid="link-request-dashboard">Go to my requests <ArrowRight size={14} className="ml-1" /></Link></div> : <form onSubmit={submit} className="mt-6 rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5"><h2 className="font-bold">Make a thoughtful request</h2><p className="mt-1 text-sm text-[#52736b]">A little context helps the owner say yes.</p><textarea required minLength={10} value={message} onChange={(event) => setMessage(event.target.value)} className="mt-4 min-h-24 w-full resize-none rounded-xl border border-[#dedbd0] bg-[#f6f3ea] p-3 text-sm outline-none focus:border-[#20443d]" placeholder="What will you use this for, and when could you collect it?" data-testid="textarea-request-message" /><Button type="submit" className="mt-3 w-full" disabled={createRequest.isPending || item.availableQuantity < 1} testId="button-send-request">{createRequest.isPending ? 'Sending request...' : 'Send request'}</Button>{createRequest.isError && <p className="mt-2 text-xs text-[#9b392e]" data-testid="status-request-error">That request couldn't be sent. Please try again.</p>}</form>}</div></div></div></Shell>;
}

function AuthCard({ mode }: { mode: 'login' | 'register' }) {
  const [, setLocation] = useLocation();
  const login = useLogin();
  const register = useRegister();
  const [error, setError] = useState('');
  const [form, setForm] = useState({ fullName: '', email: '', password: '', department: '', college: '', role: 'STUDENT' as 'STUDENT' | 'ORGANIZATION' });
  const isRegister = mode === 'register';
  const submit = (event: FormEvent) => { event.preventDefault(); setError(''); const done = (result: { token: string }) => { localStorage.setItem('campusloop_token', result.token); queryClient.invalidateQueries({ queryKey: getGetMeQueryKey() }); setLocation('/dashboard'); }; if (isRegister) register.mutate({ data: form }, { onSuccess: done, onError: () => setError('We could not create that account. Check your details and try again.') }); else login.mutate({ data: { email: form.email, password: form.password } }, { onSuccess: done, onError: () => setError('That email and password combination did not work.') }); };
  return <div className="grid min-h-[100dvh] lg:grid-cols-[.9fr_1.1fr]"><div className="hidden bg-[#20443d] p-12 text-[#f8f4e9] lg:flex lg:flex-col"><Logo dark /><div className="mt-auto max-w-md"><p className="mono text-[#e8d26e]">A better kind of campus economy</p><h1 className="display mt-5 text-5xl font-semibold leading-[1.02]">The things we share say a lot about us.</h1><p className="mt-6 leading-7 text-[#c5d2c8]">CampusLoop keeps resources in motion between the people who can use them.</p><div className="mt-12 flex gap-6 border-t border-[#315d54] pt-5 text-sm text-[#c5d2c8]"><span><strong className="block text-2xl text-[#f8f4e9]">01</strong>campus only</span><span><strong className="block text-2xl text-[#f8f4e9]">02</strong>real people</span><span><strong className="block text-2xl text-[#f8f4e9]">03</strong>less waste</span></div></div></div><div className="flex items-center justify-center bg-[#f6f3ea] px-5 py-10"><div className="w-full max-w-[430px]"><div className="mb-10 lg:hidden"><Logo /></div><p className="mono text-[#ae7620]">{isRegister ? 'Join the exchange' : 'Welcome back'}</p><h1 className="display mt-3 text-4xl font-semibold tracking-tight">{isRegister ? 'Make something useful available.' : 'Good to see you again.'}</h1><p className="mt-3 text-sm leading-6 text-[#52736b]">{isRegister ? 'Create a campus account and start sharing resources with people nearby.' : 'Sign in to keep your requests and listings moving.'}</p><form onSubmit={submit} className="mt-8 space-y-4">{isRegister && <Field label="Full name" value={form.fullName} onChange={(value) => setForm({ ...form, fullName: value })} placeholder="Amara Okafor" testId="input-full-name" /> }<Field label="Campus email" type="email" value={form.email} onChange={(value) => setForm({ ...form, email: value })} placeholder="you@campus.edu" testId="input-email" /><Field label="Password" type="password" value={form.password} onChange={(value) => setForm({ ...form, password: value })} placeholder={isRegister ? 'At least 8 characters' : 'Your password'} testId="input-password" />{isRegister && <><div className="grid gap-4 sm:grid-cols-2"><Field label="Department" value={form.department} onChange={(value) => setForm({ ...form, department: value })} placeholder="Biology" testId="input-department" /><Field label="College" value={form.college} onChange={(value) => setForm({ ...form, college: value })} placeholder="College of Science" testId="input-college" /></div><label className="block text-sm font-semibold">I am joining as<select value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value as typeof form.role })} className="mt-2 h-11 w-full rounded-xl border border-[#d6d1c2] bg-[#fbfaf5] px-3 text-sm outline-none focus:border-[#20443d]" data-testid="select-role"><option value="STUDENT">A student</option><option value="ORGANIZATION">An organization</option></select></label></>}{error && <p className="rounded-xl bg-[#f6ded7] p-3 text-sm text-[#9b392e]" data-testid="status-auth-error">{error}</p>}<Button type="submit" className="mt-3 w-full py-3" disabled={login.isPending || register.isPending} testId="button-submit-auth">{login.isPending || register.isPending ? 'One moment...' : isRegister ? 'Create my account' : 'Sign in'}</Button></form><p className="mt-7 text-center text-sm text-[#52736b]">{isRegister ? 'Already part of the loop?' : 'New to CampusLoop?'} <Link href={isRegister ? '/login' : '/register'} className="font-bold text-[#20443d] underline decoration-[#e8d26e] decoration-2 underline-offset-4" data-testid="link-auth-switch">{isRegister ? 'Sign in' : 'Create an account'}</Link></p></div></div></div>;
}

function Field({ label, value, onChange, placeholder, type = 'text', testId }: { label: string; value: string; onChange: (value: string) => void; placeholder: string; type?: string; testId: string }) {
  return <label className="block text-sm font-semibold">{label}<input required type={type} value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="mt-2 h-11 w-full rounded-xl border border-[#d6d1c2] bg-[#fbfaf5] px-3 text-sm font-normal outline-none placeholder:text-[#9caaa1] focus:border-[#20443d] focus:ring-2 focus:ring-[#20443d]/10" data-testid={testId} /></label>;
}

function RequestRow({ item, incoming = false, onRefresh }: { item: ItemRequest; incoming?: boolean; onRefresh: () => void }) {
  const accept = useAcceptRequest(); const reject = useRejectRequest(); const cancel = useCancelRequest(); const complete = useCompleteRequest();
  const busy = accept.isPending || reject.isPending || cancel.isPending || complete.isPending;
  const run = (fn: { mutate: (variables: { id: number }, options?: { onSuccess?: () => void }) => void }, id: number) => fn.mutate({ id }, { onSuccess: onRefresh });
  return <div className="flex flex-col gap-4 rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-4 sm:flex-row sm:items-center" data-testid={`row-request-${item.id}`}><div className="grid size-12 shrink-0 place-items-center rounded-xl bg-[#c6dce1] text-[#20443d]"><ClipboardList size={21} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate font-bold">{item.listing.title}</p><Status status={item.status} /></div><p className="mt-1 line-clamp-1 text-sm text-[#52736b]">“{item.message}”</p><p className="mt-2 text-xs text-[#78958b]">{incoming ? `From ${item.requester.fullName}` : `To ${item.owner.fullName}`} · {dateLabel(item.createdAt)}</p></div><div className="flex gap-2">{incoming && item.status === 'PENDING' && <><Button variant="cream" className="px-3 py-2 text-xs" onClick={() => run(accept, item.id)} disabled={busy} testId={`button-accept-${item.id}`}>Accept</Button><Button variant="outline" className="px-3 py-2 text-xs" onClick={() => run(reject, item.id)} disabled={busy} testId={`button-reject-${item.id}`}>Decline</Button></>}{!incoming && item.status === 'PENDING' && <Button variant="outline" className="px-3 py-2 text-xs" onClick={() => run(cancel, item.id)} disabled={busy} testId={`button-cancel-${item.id}`}>Cancel</Button>}{item.status === 'ACCEPTED' && <Button variant="primary" className="px-3 py-2 text-xs" onClick={() => run(complete, item.id)} disabled={busy} testId={`button-complete-${item.id}`}>Mark complete</Button>}</div></div>;
}

function Status({ status }: { status: string }) {
  const style = status === 'ACCEPTED' || status === 'COMPLETED' ? 'bg-[#dcebd8] text-[#315d38]' : status === 'REJECTED' || status === 'CANCELLED' ? 'bg-[#f6ded7] text-[#9b392e]' : 'bg-[#f6edc9] text-[#8a6518]';
  return <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.08em] ${style}`} data-testid={`status-${status.toLowerCase()}`}>{pretty(status)}</span>;
}

function ListingEditor({ existing, onClose, onSaved }: { existing?: Listing; onClose: () => void; onSaved: () => void }) {
  const categories = useListCategories(); const create = useCreateListing(); const update = useUpdateListing();
  const [form, setForm] = useState({ title: existing?.title || '', description: existing?.description || '', categoryId: String(existing?.category.id || ''), condition: (existing?.condition || 'GOOD') as Condition, quantity: String(existing?.quantity || 1), location: existing?.location || '', listingType: (existing?.listingType || 'DONATE') as ListingType, tags: existing?.tags.join(', ') || '' });
  const change = (key: string, value: string) => setForm((old) => ({ ...old, [key]: value }));
  const submit = (event: FormEvent) => { event.preventDefault(); const payload: ListingInput = { title: form.title, description: form.description, categoryId: Number(form.categoryId), condition: form.condition, quantity: Number(form.quantity), location: form.location, listingType: form.listingType, tags: form.tags.split(',').map((tag) => tag.trim()).filter(Boolean) }; const opts = { onSuccess: () => { onSaved(); onClose(); } }; existing ? update.mutate({ id: existing.id, data: payload }, opts) : create.mutate({ data: payload }, opts); };
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#20443d]/40 p-4" onMouseDown={(event) => event.currentTarget === event.target && onClose()}><div className="max-h-[90dvh] w-full max-w-[600px] overflow-y-auto rounded-3xl bg-[#fbfaf5] p-6 shadow-2xl sm:p-8"><div className="flex items-start justify-between"><div><p className="mono text-[#ae7620]">{existing ? 'Edit a resource' : 'Share with campus'}</p><h2 className="display mt-2 text-3xl font-semibold">{existing ? 'Keep the details fresh.' : 'Put something useful back in rotation.'}</h2></div><button onClick={onClose} className="grid size-9 place-items-center rounded-full hover:bg-[#e9eee6]" data-testid="button-close-editor"><X size={18} /></button></div><form onSubmit={submit} className="mt-7 space-y-4"><Field label="Title" value={form.title} onChange={(value) => change('title', value)} placeholder="e.g. Folding display boards" testId="input-listing-title" /><label className="block text-sm font-semibold">Description<textarea required minLength={10} value={form.description} onChange={(event) => change('description', event.target.value)} className="mt-2 min-h-24 w-full rounded-xl border border-[#d6d1c2] bg-[#f6f3ea] p-3 text-sm font-normal outline-none focus:border-[#20443d]" placeholder="What should someone know before requesting this?" data-testid="textarea-listing-description" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-semibold">Category<select required value={form.categoryId} onChange={(event) => change('categoryId', event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d6d1c2] bg-[#f6f3ea] px-3 text-sm font-normal" data-testid="select-listing-category"><option value="">Choose one</option>{categories.data?.map((category) => <option value={category.id} key={category.id}>{category.name}</option>)}</select></label><Field label="Pickup spot" value={form.location} onChange={(value) => change('location', value)} placeholder="Student union, room 204" testId="input-listing-location" /></div><div className="grid gap-4 sm:grid-cols-3"><label className="block text-sm font-semibold">Condition<select value={form.condition} onChange={(event) => change('condition', event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d6d1c2] bg-[#f6f3ea] px-2 text-xs font-normal" data-testid="select-listing-condition">{['NEW', 'LIKE_NEW', 'GOOD', 'USED', 'NEEDS_REPAIR'].map((value) => <option value={value} key={value}>{pretty(value)}</option>)}</select></label><Field label="Quantity" value={form.quantity} onChange={(value) => change('quantity', value)} placeholder="1" testId="input-listing-quantity" /><label className="block text-sm font-semibold">Type<select value={form.listingType} onChange={(event) => change('listingType', event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#d6d1c2] bg-[#f6f3ea] px-2 text-xs font-normal" data-testid="select-listing-type"><option value="DONATE">Donate</option><option value="EXCHANGE">Exchange</option></select></label></div><Field label="Tags (comma separated)" value={form.tags} onChange={(value) => change('tags', value)} placeholder="course materials, reusable" testId="input-listing-tags" /><Button type="submit" className="w-full py-3" disabled={create.isPending || update.isPending} testId="button-save-listing">{create.isPending || update.isPending ? 'Saving...' : existing ? 'Save changes' : 'Publish resource'}</Button></form></div></div>;
}

const dashboardMetrics: Array<[string, number, LucideIcon]> = [['Listed', 0, PackageOpen], ['Requests made', 0, ClipboardList], ['Items reused', 0, HeartHandshake], ['Incoming', 0, Bell]];

function DashboardPage() {
  const { data: me } = useGetMe(); const dashboard = useGetDashboard(); const requests = useListRequests({ view: 'all' }); const [editor, setEditor] = useState<Listing | null | false>(false); const [, setLocation] = useLocation(); const remove = useDeleteListing();
  const refresh = () => { queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); queryClient.invalidateQueries({ queryKey: getListRequestsQueryKey({ view: 'all' }) }); };
  if (dashboard.isLoading) return <Shell><Page title="Your dashboard" detail="Gathering your campus activity..."><LoadingState rows={4} /></Page></Shell>;
  if (dashboard.isError || !dashboard.data) return <Shell><Page title="Your dashboard"><ErrorState retry={() => dashboard.refetch()} /></Page></Shell>;
  const data = dashboard.data;
  const metricItems = dashboardMetrics.map(([label, , icon], index) => [label, [data.itemsListed, data.requestsMade, data.itemsReused, data.incomingRequests][index], icon] as [string, number, LucideIcon]);
  return <Shell><Page eyebrow={me?.role === 'ORGANIZATION' ? 'Organization desk' : 'Your campus desk'} title={`Keep the loop moving${me ? `, ${me.fullName.split(' ')[0]}` : ''}.`} detail="See what you have shared, what you have requested, and what needs your next move." action={<Button variant="cream" onClick={() => setEditor(null)} testId="button-open-create-listing"><Plus size={17} /> Share an item</Button>}><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{metricItems.map(([label, value, Icon], index) => <div key={String(label)} className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5" data-testid={`metric-${String(label).toLowerCase().replaceAll(' ', '-')}`}><div className={`mb-6 grid size-9 place-items-center rounded-xl ${colors[index]}`}><Icon size={17} /></div><p className="mono text-[#78958b]">{label}</p><p className="mt-1 text-3xl font-bold">{value}</p></div>)}</div><div className="mt-9 grid gap-8 xl:grid-cols-[1.15fr_.85fr]"><div><div className="mb-4 flex items-center justify-between"><h2 className="display text-2xl font-semibold">Your requests</h2><Link href="/marketplace" className="text-sm font-bold text-[#52736b]" data-testid="link-dashboard-browse">Browse more <ArrowRight className="inline" size={14} /></Link></div>{data.myRequests.length === 0 ? <Notice title="Your request list is clear" detail="Find something useful in the marketplace and start your first handoff." action={<Link href="/marketplace" className="inline-flex rounded-xl bg-[#20443d] px-4 py-2.5 text-sm font-semibold text-[#f8f4e9]" data-testid="link-dashboard-empty-browse">Browse resources</Link>} /> : <div className="space-y-3">{data.myRequests.slice(0, 5).map((item) => <RequestRow item={item} key={item.id} onRefresh={refresh} />)}</div>}</div><div><div className="mb-4 flex items-center justify-between"><h2 className="display text-2xl font-semibold">Incoming requests</h2><span className="mono text-[#78958b]">{data.incoming.length} total</span></div>{data.incoming.length === 0 ? <Notice title="No new requests" detail="When someone asks for one of your resources, it will appear here." /> : <div className="space-y-3">{data.incoming.slice(0, 5).map((item) => <RequestRow item={item} incoming key={item.id} onRefresh={refresh} />)}</div>}</div></div><div className="mt-10"><div className="mb-4 flex items-center justify-between"><h2 className="display text-2xl font-semibold">Your shared resources</h2><span className="mono text-[#78958b]">{data.myListings.length} listed</span></div>{data.myListings.length === 0 ? <Notice title="Your shelf is waiting" detail="Share a spare resource and make it easier for someone else to get through the semester." action={<Button variant="cream" onClick={() => setEditor(null)} testId="button-empty-share"><Plus size={16} /> Share something</Button>} /> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{data.myListings.map((item, index) => <div key={item.id} className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-4" data-testid={`card-my-listing-${item.id}`}><div className="flex items-start gap-3"><div className={`grid size-12 shrink-0 place-items-center rounded-xl ${colors[index % colors.length]}`}><PackageOpen size={20} /></div><div className="min-w-0 flex-1"><p className="truncate font-bold">{item.title}</p><p className="mt-1 text-xs text-[#52736b]">{item.availableQuantity} of {item.quantity} available · {pretty(item.status)}</p></div></div><div className="mt-4 flex gap-2"><Button variant="outline" className="flex-1 px-3 py-2 text-xs" onClick={() => setEditor(item)} testId={`button-edit-listing-${item.id}`}><Pencil size={13} /> Edit</Button><Button variant="danger" className="px-3 py-2 text-xs" onClick={() => { if (window.confirm('Remove this resource from the marketplace?')) remove.mutate({ id: item.id }, { onSuccess: refresh }); }} testId={`button-delete-listing-${item.id}`}><Trash2 size={13} /></Button></div></div>)}</div>}</div></Page>{editor !== false && <ListingEditor existing={editor || undefined} onClose={() => setEditor(false)} onSaved={refresh} />}</Shell>;
}

function ImpactPage() {
  const impact = useGetImpact();
  if (impact.isLoading) return <Shell><Page title="Campus impact"><LoadingState rows={3} /></Page></Shell>;
  if (impact.isError || !impact.data) return <Shell><Page title="Campus impact"><ErrorState retry={() => impact.refetch()} /></Page></Shell>;
  const data = impact.data; const total = data.donations + data.exchanges;
  return <Shell><Page eyebrow="The bigger picture" title="Reuse leaves a trace." detail="These are the exchanges that have actually happened through CampusLoop — no estimates, no inflated promises." action={<div className="rounded-xl bg-[#dcebd8] px-4 py-2.5 text-sm font-bold text-[#315d38]"><span className="mr-2 inline-block size-2 rounded-full bg-[#5a9c65]" />Live campus data</div>}><div className="relative overflow-hidden rounded-[28px] bg-[#20443d] p-7 text-[#f8f4e9] sm:p-10"><div className="absolute -right-20 -top-24 size-80 rounded-full border-[55px] border-[#315d54]" /><div className="relative max-w-xl"><p className="mono text-[#e8d26e]">Our shared tally</p><p className="display mt-4 text-7xl font-semibold tracking-[-.06em] sm:text-8xl" data-testid="text-impact-reused">{data.itemsReused.toLocaleString()}</p><p className="mt-2 text-lg text-[#c5d2c8]">items have stayed in use on campus.</p><div className="mt-10 grid max-w-lg grid-cols-2 gap-6 border-t border-[#315d54] pt-5 text-sm"><div><p className="text-2xl font-bold text-[#e8d26e]">{data.completedExchanges.toLocaleString()}</p><p className="mt-1 text-[#c5d2c8]">completed exchanges</p></div><div><p className="text-2xl font-bold text-[#e8d26e]">{total.toLocaleString()}</p><p className="mt-1 text-[#c5d2c8]">total handoffs</p></div></div></div></div><div className="mt-6 grid gap-4 md:grid-cols-3"><ImpactCard label="Donations" value={data.donations} copy="Resources given freely to another member of campus." icon={Sprout} /><ImpactCard label="Exchanges" value={data.exchanges} copy="Items traded between people who had something to offer." icon={HeartHandshake} /><ImpactCard label="Completion rate" value={total ? `${Math.round((data.completedExchanges / total) * 100)}%` : '—'} copy="Of all handoffs, marked complete by both sides." icon={Check} /></div><div className="mt-10 grid gap-5 rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-6 md:grid-cols-[auto_1fr] md:items-center"><div className="grid size-14 place-items-center rounded-2xl bg-[#e8d26e] text-[#20443d]"><CircleHelp size={25} /></div><div><h2 className="font-bold">Why count exchanges?</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-[#52736b]">An item reused is an item we did not need to buy again or throw away. We count completed exchanges and donations recorded in CampusLoop, so this page stays grounded in what our community actually did.</p></div></div></Page></Shell>;
}

function ImpactCard({ label, value, copy, icon: Icon }: { label: string; value: string | number; copy: string; icon: typeof Sprout }) {
  return <div className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5"><div className="flex items-center justify-between"><p className="mono text-[#ae7620]">{label}</p><Icon size={19} className="text-[#789c78]" /></div><p className="mt-5 text-4xl font-bold">{value}</p><p className="mt-2 text-sm leading-6 text-[#52736b]">{copy}</p></div>;
}

function ProfilePage() {
  const me = useGetMe();
  if (me.isLoading) return <Shell><Page title="Your profile"><LoadingState rows={2} /></Page></Shell>;
  if (me.isError || !me.data) return <Shell><Page title="Your profile"><ErrorState retry={() => me.refetch()} /></Page></Shell>;
  const user = me.data;
  return <Shell><Page eyebrow="Your campus identity" title="Your profile" detail="A few details help people know who they are sharing with."><div className="grid gap-6 lg:grid-cols-[.72fr_1.28fr]"><div className="rounded-2xl bg-[#20443d] p-7 text-[#f8f4e9]"><Avatar user={user} size="size-20" /><h2 className="display mt-6 text-3xl font-semibold" data-testid="text-profile-name">{user.fullName}</h2><p className="mt-2 text-sm text-[#c5d2c8]">{user.email}</p><div className="mt-8 space-y-3 border-t border-[#315d54] pt-5 text-sm"><div className="flex justify-between"><span className="text-[#9db8aa]">Role</span><span>{pretty(user.role)}</span></div><div className="flex justify-between"><span className="text-[#9db8aa]">Member since</span><span>{dateLabel(user.createdAt)}</span></div><div className="flex justify-between"><span className="text-[#9db8aa]">Status</span><span className="text-[#e8d26e]">{pretty(user.status)}</span></div></div></div><div className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-6"><div className="flex items-center justify-between border-b border-[#e9e4d8] pb-5"><div><p className="mono text-[#ae7620]">Campus details</p><h2 className="display mt-2 text-2xl font-semibold">Where you plug in</h2></div><span className="grid size-10 place-items-center rounded-xl bg-[#dcebd8] text-[#315d38]"><GraduationCap size={19} /></span></div><div className="mt-5 grid gap-5 sm:grid-cols-2"><div><p className="mono text-[#78958b]">Department</p><p className="mt-2 font-semibold" data-testid="text-profile-department">{user.department}</p></div><div><p className="mono text-[#78958b]">College</p><p className="mt-2 font-semibold" data-testid="text-profile-college">{user.college}</p></div><div><p className="mono text-[#78958b]">Email</p><p className="mt-2 break-all font-semibold">{user.email}</p></div><div><p className="mono text-[#78958b]">Member type</p><p className="mt-2 font-semibold">{pretty(user.role)}</p></div></div><div className="mt-8 rounded-xl bg-[#f6f3ea] p-4 text-sm leading-6 text-[#52736b]"><LockKeyhole className="mr-2 inline text-[#ae7620]" size={16} />CampusLoop only shows your name, role, and department to other members. Your email stays private.</div></div></div></Page></Shell>;
}

function AdminPage() {
  const stats = useGetAdminStatistics(); const users = useListAdminUsers(); const listings = useListAdminListings(); const disable = useDisableUser(); const remove = useRemoveAdminListing();
  const pending = useListRequests({ view: 'incoming' });
  const refresh = () => { queryClient.invalidateQueries({ queryKey: getGetAdminStatisticsQueryKey() }); queryClient.invalidateQueries({ queryKey: getListAdminUsersQueryKey() }); queryClient.invalidateQueries({ queryKey: getListAdminListingsQueryKey() }); queryClient.invalidateQueries({ queryKey: getListRequestsQueryKey({ view: 'incoming' }) }); };
  const anyLoading = stats.isLoading || users.isLoading || listings.isLoading || pending.isLoading;
  if (anyLoading) return <Shell><Page title="Admin desk" detail="Loading moderation tools..."><LoadingState rows={5} /></Page></Shell>;
  if (stats.isError || users.isError || listings.isError || pending.isError || !stats.data) return <Shell><Page title="Admin desk"><ErrorState retry={refresh} /></Page></Shell>;
  const adminMetrics: Array<[string, number, LucideIcon]> = [['Members', stats.data.totalUsers, Users], ['Listings', stats.data.totalListings, PackageOpen], ['Available items', stats.data.availableItems, Sprout], ['Pending requests', stats.data.pendingRequests, ClipboardList], ['Completed exchanges', stats.data.completedExchanges, Check], ['Categories', stats.data.totalCategories, Compass]];
  return <Shell><Page eyebrow="Keep the loop healthy" title="Admin desk" detail="A focused view of campus activity, people, and resources that need attention."><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{adminMetrics.map(([label, value, Icon], index) => <div className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5" key={String(label)} data-testid={`admin-stat-${String(label).toLowerCase().replaceAll(' ', '-')}`}><div className={`grid size-9 place-items-center rounded-xl ${colors[index % colors.length]}`}><Icon size={17} /></div><p className="mono mt-5 text-[#78958b]">{label}</p><p className="mt-1 text-3xl font-bold">{value}</p></div>)}</div><div className="mt-9 grid gap-8 xl:grid-cols-2"><AdminSection title="People on Campus" count={users.data?.length || 0}>{users.data?.slice(0, 8).map((user) => <div className="flex items-center gap-3 border-b border-[#e9e4d8] py-3 last:border-0" key={user.id} data-testid={`row-admin-user-${user.id}`}><Avatar user={user} size="size-9" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{user.fullName}</p><p className="truncate text-xs text-[#52736b]">{user.department} · {pretty(user.role)}</p></div><Status status={user.status} />{user.status === 'ACTIVE' && user.role !== 'ADMIN' && <Button variant="danger" className="px-2.5 py-2 text-xs" onClick={() => disable.mutate({ id: user.id }, { onSuccess: refresh })} disabled={disable.isPending} testId={`button-disable-user-${user.id}`}>Disable</Button>}</div>)}</AdminSection><AdminSection title="Listings to review" count={listings.data?.length || 0}>{listings.data?.slice(0, 8).map((item) => <div className="flex items-center gap-3 border-b border-[#e9e4d8] py-3 last:border-0" key={item.id} data-testid={`row-admin-listing-${item.id}`}><div className="grid size-9 place-items-center rounded-xl bg-[#e7d6ae]"><PackageOpen size={16} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{item.title}</p><p className="truncate text-xs text-[#52736b]">{item.owner.fullName} · {pretty(item.status)}</p></div><Button variant="danger" className="px-2.5 py-2 text-xs" onClick={() => { if (window.confirm('Remove this listing?')) remove.mutate({ id: item.id }, { onSuccess: refresh }); }} disabled={remove.isPending} testId={`button-remove-listing-${item.id}`}><Trash2 size={13} /></Button></div>)}</AdminSection></div><div className="mt-8"><div className="mb-4 flex items-center justify-between"><h2 className="display text-2xl font-semibold">Incoming requests</h2><span className="mono text-[#78958b]">{pending.data?.length || 0} pending</span></div>{pending.data?.length ? <div className="space-y-3">{pending.data.slice(0, 6).map((item) => <RequestRow item={item} incoming key={item.id} onRefresh={refresh} />)}</div> : <Notice title="No requests need review" detail="The campus exchange is caught up for now." />}</div></Page></Shell>;
}

function AdminSection({ title, count, children }: { title: string; count: number; children: ReactNode }) {
  return <section className="rounded-2xl border border-[#dedbd0] bg-[#fbfaf5] p-5"><div className="mb-3 flex items-center justify-between"><h2 className="display text-2xl font-semibold">{title}</h2><span className="mono text-[#78958b]">{count} total</span></div>{children}</section>;
}

function AppRouter() {
  return <ErrorBoundary><Switch><Route path="/" component={Landing} /><Route path="/marketplace" component={Marketplace} /><Route path="/marketplace/:id" component={ListingDetail} /><Route path="/login"><AuthCard mode="login" /></Route><Route path="/register"><AuthCard mode="register" /></Route><Route path="/dashboard" component={DashboardPage} /><Route path="/impact" component={ImpactPage} /><Route path="/profile" component={ProfilePage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

export default function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}